    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["satelliteCount","centerLabel","accentColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  satelliteCount: 6,
  centerLabel: "V",
  accentColor: "#a855f7",
  speed: 1,
};

type EcosystemConstellationElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof EcosystemConstellationBase>;

const EcosystemConstellationInner = forwardRef<
  HTMLDivElement,
  EcosystemConstellationElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<EcosystemConstellation>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <EcosystemConstellationBase
          {...(componentProps as unknown as ComponentProps<typeof EcosystemConstellationBase>)}
        />
      </div>
    </Sequence>
  );
});

export const EcosystemConstellation = Interactive.withSchema({
  Component: EcosystemConstellationInner,
  componentName: "<EcosystemConstellation>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
